#!/usr/bin/env node
// graphifyy is a redirect to @sentropic/graphify. Delegate to its CLI.
// Resolve via the package main (the only path guaranteed by "exports"); cli.js
// sits next to it in dist/. Spawn it so it works whether it is ESM or CJS.
const path = require("node:path");
const { spawnSync } = require("node:child_process");
const cliPath = path.join(path.dirname(require.resolve("@sentropic/graphify")), "cli.js");
const result = spawnSync(process.execPath, [cliPath, ...process.argv.slice(2)], { stdio: "inherit" });
process.exit(result.status ?? 0);
